-- Get size and row count for orders_archive_2023 and top large tables
SELECT 'archive_size' as what, pg_size_pretty(pg_total_relation_size('orders_archive_2023'::regclass)) AS size;
SELECT 'archive_rows' as what, count(*) FROM orders_archive_2023;

-- Top 20 largest user tables
SELECT schemaname, relname AS table_name, pg_size_pretty(pg_total_relation_size(relid)) AS total_size
FROM pg_catalog.pg_statio_user_tables
ORDER BY pg_total_relation_size(relid) DESC
LIMIT 20;

